private void enlarge(final int size){
    if (size <= 0){
        return; // nothing to enlarge
    }
    // current length of data stored
    final int currentLen = len; // 'len' is the number of valid bytes currently stored
    final int currentCap = bytes != null ? bytes.length : 0;
    final int required = currentLen + size;

    if (required <= currentCap){
        return; // already enough capacity
    }

    // compute a new capacity, usually growing by 50%
    int newCap = Math.max(required, currentCap * 3 / 2);
    if (newCap == 0){
        newCap = required; // initial allocation, when array is empty
    }

    byte[] newBytes = new byte[newCap];
    if (bytes != null && currentLen > 0){
        System.arraycopy(bytes, 0, newBytes, 0, currentLen);
    }
    bytes = newBytes;
}

private void enlarge(final int size) {
    if (size <= 0) {
        return; // nothing to enlarge
    }
    final int currentCapacity = array.length;
    final int required = arrayOffset + arrayLength + size;
    int newCapacity;
    try {
        newCapacity = Math.max(currentCapacity + (currentCapacity >> 1), required);
    } catch (ArithmeticException e) {
        throw new OutOfMemoryError("Cannot enlarge byte vector: capacity overflow");
    }
    if (newCapacity < 64) {
        newCapacity = 64;
    }
    byte[] newArray = new byte[newCapacity];
    System.arraycopy(array, 0, newArray, 0, arrayOffset + arrayLength);
    array = newArray;
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    try {
        int oldCap = (buf == null) ? 0 : buf.length;
        // Avoid integer overflow when calculating the new capacity
        int newCap = oldCap + size;
        if (newCap < 0) { // overflow occurred
            newCap = Integer.MAX_VALUE;
        }
        byte[] newBuf = new byte[newCap];
        if (buf != null) {
            System.arraycopy(buf, 0, newBuf, 0, buf.length);
        }
        buf = newBuf;
    } catch (OutOfMemoryError e) {
        // Rethrow as an IllegalStateException to indicate the vector cannot grow
        throw new IllegalStateException("Unable to enlarge byte vector due to memory constraints", e);
    }
}

private void enlarge(final int size){
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    if (size == 0) {
        return;
    }
    try {
        int newCapacity = Math.addExact(buffer.length, size);
        buffer = java.util.Arrays.copyOf(buffer, newCapacity);
    } catch (ArithmeticException e) {
        throw new IllegalStateException("Capacity overflow while enlarging byte vector", e);
    } catch (OutOfMemoryError e) {
        throw new IllegalStateException("Unable to enlarge byte vector due to insufficient memory", e);
    }
}

private void enlarge(final int size) {
    // No need to enlarge for non-positive requests
    if (size <= 0) {
        return;
    }

    // If no underlying storage exists, create an initial array
    if (buffer == null) {
        buffer = new byte[Math.max(size, 16)];
        return;
    }

    // Determine the space currently available
    final int currentCapacity = buffer.length;
    final int requiredCapacity = count + size;

    // If the current capacity can accommodate the new bytes, do nothing
    if (requiredCapacity <= currentCapacity) {
        return;
    }

    // Compute a new capacity: try to double the existing one but
    // make sure it meets the required capacity and guards against overflow
    int newCapacity = currentCapacity << 1;
    if (newCapacity <= 0 || newCapacity < requiredCapacity) {
        newCapacity = requiredCapacity;
    }

    // Allocate new storage and copy existing data
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer, 0, newBuffer, 0, count);
    buffer = newBuffer;
}

