private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        // Cannot perform a right rotation if there is no left child
        return node;
    }
    // Perform rotation
    node.left = left.right;
    left.right = node;
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> leftChild = node.left;
    TreeNode<T> leftRight = leftChild.right;

    // Detach left-right subtree from left child
    node.left = leftRight;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // Attach node as right child of left child
    leftChild.right = node;
    node.parent = leftChild;

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if(node == null || node.left == null){
        return node;
    }
    TreeNode<T> left = node.left;
    node.left = left.right;
    left.right = node;
    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        return node;
    }

    // = node.left.right
    node.left = left.right;
    if (node.left != null) {
        node.left.parent = node;
    }

    // = node
    left.right = node;

    // Update parent links (if the node had a parent)
    left.parent = node.parent;
    node.parent = left;

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> pivot = node.left;

    // Move pivot's right subtree to node's left
    node.left = pivot.right;
    if (pivot.right != null) {
        pivot.right.parent = node;
    }

    // Perform rotation
    pivot.right = node;

    // Update parents
    pivot.parent = node.parent;
    node.parent = pivot;

    return pivot;
}

