public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("ClassPath vector cannot be null");
    }
    if (dir == null || dir.trim().isEmpty()) {
        throw new IllegalArgumentException("Directory path cannot be null or empty");
    }

    File folder = new File(dir);
    if (!folder.exists() || !folder.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a valid directory: " + dir);
    }

    File[] jarFiles = folder.listFiles((d, name) -> name.toLowerCase().endsWith(".jar"));
    if (jarFiles == null) {
        // In case of an IO error or no files found, just return without adding
        return;
    }

    for (File jar : jarFiles) {
        if (jar.isFile()) {
            try {
                cpV.add(jar.toURI().toURL());
            } catch (MalformedURLException e) {
                // This should not happen with a file URI, but if it does, skip this file
                // Optionally log the error here
            }
        }
    }
}

