public String format(LoggingEvent event){
    if(event == null){
        return "";
    }
    try{
        long ts = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        String time = sdf.format(new java.util.Date(ts));
        String level = event.getLevel() == null ? "UNKNOWN" : event.getLevel().toString();
        String logger = event.getLoggerName() == null ? "UNKNOWN" : event.getLoggerName();
        Object msgObj = event.getMessage();
        String msg = msgObj == null ? "" : msgObj.toString();
        return String.format("[%s] [%s] %s - %s", time, level, logger, msg);
    }catch(Exception e){
        return "";
    }
}

public String format(LoggingEvent event) {
    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();

        // Append level
        sb.append("[");
        sb.append(event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN");
        sb.append("] ");

        // Append formatted timestamp
        long ts = event.getTimeStamp();
        if (ts > 0) {
            String formattedTime = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS")
                    .format(new java.util.Date(ts));
            sb.append(formattedTime).append(" ");
        }

        // Append logger name
        sb.append(event.getLoggerName() != null ? event.getLoggerName() : "UnknownLogger");
        sb.append(": ");

        // Append message
        String message = event.getRenderedMessage();
        if (message == null) {
            message = event.getMessage() != null ? event.getMessage().toString() : "";
        }
        sb.append(message);

        // Append exception stack trace if present
        if (event.getThrowableInformation() != null) {
            Throwable t = event.getThrowableInformation().getThrowable();
            sb.append(System.lineSeparator()).append(t.toString());
            for (StackTraceElement ste : t.getStackTrace()) {
                sb.append(System.lineSeparator()).append("\tat ").append(ste.toString());
            }
        }

        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected error during formatting
        return "";
    }
}

public String format(LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Determine the format pattern. If this class provides a getPattern() method,
        // use it; otherwise fall back to a sensible default.
        String pattern;
        try {
            pattern = this.getPattern();
        } catch (Exception e) {
            pattern = "%d [%p] %c - %m%n";
        }
        // Handle null pattern
        if (pattern == null) {
            pattern = "%d [%p] %c - %m%n";
        }
        // Replace tokens in the pattern
        String formatted = pattern;
        // Message
        Object msgObj = event.getMessage();
        String message = msgObj != null ? msgObj.toString() : "";
        formatted = formatted.replace("%m", message);
        // Timestamp
        long timeMillis = event.getTimeStamp();
        String dateStr = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss,SSS")
                .format(new java.util.Date(timeMillis));
        formatted = formatted.replace("%d", dateStr);
        // Level
        String level = event.getLevel() != null ? event.getLevel().toString() : "";
        formatted = formatted.replace("%p", level);
        // Logger name
        String loggerName = event.getLoggerName() != null ? event.getLoggerName() : "";
        formatted = formatted.replace("%c", loggerName);
        // Thread name
        String threadName = event.getThreadName() != null ? event.getThreadName() : "";
        formatted = formatted.replace("%t", threadName);
        // Newline
        formatted = formatted.replace("%n", System.lineSeparator());
        return formatted;
