public static void forceDeleteOnExit(File file) throws IOException {
    Objects.requireNonNull(file, "file must not be null");
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            Deque<File> stack = new ArrayDeque<>();
            stack.push(file);
            while (!stack.isEmpty()) {
                File current = stack.pop();
                if (current.isDirectory()) {
                    File[] children = current.listFiles();
                    if (children != null) {
                        for (File child : children) {
                            stack.push(child);
                        }
                    }
                }
                try {
                    if (!current.delete() && current.exists()) {
                        // Deletion failed; ignore as we can't throw from shutdown hook
                    }
                } catch (SecurityException ignored) {
                    // Ignore deletion failure due to permissions
                }
            }
        } catch (Exception e) {
            // Any unexpected exception during deletion is ignored
        }
    }));
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    try {
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children == null) {
                throw new IOException("Unable to list contents of directory: " + file);
            }
            for (File child : children) {
                forceDeleteOnExit(child);
            }
        }
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Permission denied to delete or schedule delete for " + file, e);
    }
}

