@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    try {
        // Define the number of vertices on each side of the bipartite graph
        final int leftCount = 3;
        final int rightCount = 3;

        // Create vertex lists for easier handling
        List<V> leftVertices = new ArrayList<>(leftCount);
        List<V> rightVertices = new ArrayList<>(rightCount);

        // Generate left side vertices
        for (int i = 0; i < leftCount; i++) {
            String name = "A" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            target.addVertex(vertex);
            leftVertices.add(vertex);
            resultMap.put(name, vertex);
        }

        // Generate right side vertices
        for (int i = 0; i < rightCount; i++) {
            String name = "B" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            target.addVertex(vertex);
            rightVertices.add(vertex);
            resultMap.put(name, vertex);
        }

        // Add all possible edges between left and right vertices to form a complete bipartite graph
        for (V u : leftVertices) {
            for (V v : rightVertices) {
                target.addEdge(u, v);
            }
        }
    } catch (Exception ex) {
        // Wrap any exception that occurs during graph construction in an IllegalStateException
        throw new IllegalStateException("Error while generating complete bipartite graph", ex);
    }
}

@Override 
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    try {
        List<V> left = new ArrayList<>();
        List<V> right = new ArrayList<>();

        // Partition vertices heuristically based on key prefixes
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            if (key.isEmpty()) {
                continue;
            }
            char firstChar = Character.toLowerCase(key.charAt(0));
            if (firstChar == 'u' || firstChar == 'l') {
                left.add(entry.getValue());
            } else {
                right.add(entry.getValue());
            }
        }

        // Ensure all vertices are present in the graph
        for (V v : left) {
            if (!target.containsVertex(v)) {
                target.addVertex(v);
            }
        }
        for (V v : right) {
            if (!target.containsVertex(v)) {
                target.addVertex(v);
            }
        }

        // Add all possible edges between left and right parts
        for (V u : left) {
            for (V v : right) {
                if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
