@Override public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // partition vertices into two sets (left and right) based on key prefix
    List<V> left = new ArrayList<>();
    List<V> right = new ArrayList<>();
    for (Map.Entry<String, V> entry : resultMap.entrySet()) {
        String key = entry.getKey();
        if (key == null) {
            continue;
        }
        char first = Character.toLowerCase(key.charAt(0));
        if (first == 'l' || first == 'a') {
            left.add(entry.getValue());
        } else {
            right.add(entry.getValue());
        }
    }
    // Fallback: if one side ended up empty, split vertices evenly
    if (left.isEmpty() || right.isEmpty()) {
        left.clear();
        right.clear();
        int i = 0;
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            if (i % 2 == 0) {
                left.add(entry.getValue());
            } else {
                right.add(entry.getValue());
            }
            i++;
        }
    }

    try {
        // ensure all vertices exist in the graph
        for (V v : resultMap.values()) {
            if (!target.containsVertex(v)) {
                target.addVertex(v);
            }
        }

        // add edges between every pair of vertices from different partitions
        for (V u : left) {
            for (V v : right) {
                if (!target.containsEdge(u, v)) {
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception e) {
        // Log or rethrow as runtime exception if desired
        throw new RuntimeException("Failed to generate complete bipartite graph", e);
    }
}

@Override
public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    try {
        // Add all vertices to the graph
        for (V vertex : resultMap.values()) {
            target.addVertex(vertex);
        }
        // Convert vertices to a list to split into two partitions
        java.util.List<V> vertices = new java.util.ArrayList<>(resultMap.values());
        int total = vertices.size();
        if (total < 2) {
            return; // Nothing to connect in a bipartite graph
        }
        // Split the list roughly in half: left side and right side
        int mid = total / 2;
        java.util.List<V> leftPartition = vertices.subList(0, mid);
        java.util.List<V> rightPartition = vertices.subList(mid, total);
        // Add edges between every pair of vertices from the two partitions
        for (V leftVertex : leftPartition) {
            for (V rightVertex : rightPartition) {
                target.addEdge(leftVertex, rightVertex);
            }
        }
    } catch (Exception ex) {
        // Wrap any exception thrown during graph construction
        throw new RuntimeException("Error generating complete bipartite graph", ex);
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph must not be null");
    }
    if (resultMap == null) {
        throw new IllegalArgumentException("Result map must not be null");
    }

    Collection<V> values = resultMap.values();
    if (values.isEmpty()) {
        return;
    }

    List<V> vertices = new ArrayList<>(values);
    int size = vertices.size();
    if (size < 2) {
        return; // Not enough vertices to form a bipartite graph
    }

    int half = size / 2;
    List<V> left = vertices.subList(0, half);
    List<V> right = vertices.subList(half, size);

    // Add vertices to the graph if they are not already present
    for (V v : vertices) {
        if (!target.containsVertex(v)) {
            target.addVertex(v);
        }
    }

    try {
        // Connect every vertex in the left partition with every vertex in the right partition
        for (V u : left) {
            for (V v : right) {
                if (!target.containsEdge(u, v) && !target.containsEdge(v, u)) {
                    target.addEdge(u, v);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to construct complete bipartite graph", e);
    }
}

