    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    // Write the message into the buffer
    int size = schema.writeTo(message, buffer);
    // Encode the size as a varint
    int val = size;
    while ((val & ~0x7F) != 0) {
        out.write((val & 0x7F) | 0x80);
        val >>>= 7;
    }
    out.write(val);
    // Write the buffer contents
    byte[] data = buffer.getBytes();
    out.write(data, 0, size);
    // Reset the buffer for future use
    buffer.clear();
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) throw new NullPointerException("OutputStream 'out' is null");
    if (message == null) throw new NullPointerException("Message 'message' is null");
    if (schema == null) throw new NullPointerException("Schema 'schema' is null");
    if (buffer == null) throw new NullPointerException("LinkedBuffer 'buffer' is null");
    try {
        // Compute the serialized size of the message
        int size = schema.getSerializedSize(message);
        // Write the size as varint
        CodedOutputStream cos = CodedOutputStream.newInstance(out);
        cos.writeRawVarint32(size);
        // Serialize the message using the provided buffer
        schema.serialize(message, cos, buffer);
        cos.flush();
        return size;
    } catch (IOException e) {
        throw e; // Preserve IOException
    } catch (Exception e) {
        throw new IOException("Failed to serialize message", e);
    }
}

