public static Class<?>[] resolveArguments(java.lang.reflect.Type genericType, java.lang.Class<?> targetType){
    try {
        if (!(genericType instanceof java.lang.reflect.ParameterizedType)) {
            return null;
        }
        java.lang.reflect.ParameterizedType pType = (java.lang.reflect.ParameterizedType) genericType;
        java.lang.reflect.Type[] actualArgs = pType.getActualTypeArguments();
        java.util.Map<java.lang.reflect.TypeVariable<?>, java.lang.reflect.Type> typeVarAssigns = new java.util.HashMap<>();
        buildTypeVarAssignments(targetType, typeVarAssigns);
        java.lang.Class<?>[] result = new java.lang.Class<?>[actualArgs.length];
        for (int i = 0; i < actualArgs.length; i++) {
            java.lang.Class<?> clazz = resolveClassFromType(actualArgs[i], typeVarAssigns);
            if (clazz == null) {
                return null;
            }
            result[i] = clazz;
        }
        return result;
    } catch (Exception e) {
        return null;
    }
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType){
    try{
        if(!(genericType instanceof ParameterizedType)){
            return null;
        }
        ParameterizedType pt = (ParameterizedType)genericType;
        Class<?> raw = (Class<?>)pt.getRawType();
        // If the target type does not relate to the raw type, we cannot resolve
        if(!raw.isAssignableFrom(targetType)){
            return null;
        }
        Type[] typeArgs = pt.getActualTypeArguments();
        Class<?>[] result = new Class<?>[typeArgs.length];
        for(int i=0;i<typeArgs.length;i++){
            Type arg = typeArgs[i];
            if(arg instanceof Class<?>){
                result[i] = (Class<?>)arg;
            }else if(arg instanceof ParameterizedType){
                Type rawArg = ((ParameterizedType)arg).getRawType();
                if(rawArg instanceof Class<?>){
                    result[i] = (Class<?>)rawArg;
                }else{
                    return null;
                }
            }else{
                // Cannot resolve type variables at runtime
                return null;
            }
        }
        return result;
    }catch(Exception e){
        return null;
    }
}

