protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate FETCH_DATA_DURATION
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be greater than zero");
    }
    // Validate input bounds
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non‑negative");
    }
    if (start > end) {
        throw new IllegalArgumentException("Start time must not be greater than end time");
    }

    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    if (start == end) {
        return ranges; // No range to split
    }

    long currentStart = start;
    while (currentStart < end) {
        long remaining = end - currentStart;
        long segmentDuration = Math.min(remaining, FETCH_DATA_DURATION);
        long currentEnd = currentStart + segmentDuration;
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Ensure start is not greater than end
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time");
    }
    // Validate the duration constant
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }

    List<TimeRange> ranges = new ArrayList<>(1);

    // If start == end, return a single zero-length range
    if (start == end) {
        ranges.add(new TimeRange(start, end));
        return ranges;
    }

    long curStart = start;
    while (curStart < end) {
        long curEnd = Math.min(curStart + FETCH_DATA_DURATION, end);
        ranges.add(new TimeRange(curStart, curEnd));
        curStart = curEnd;
    }

    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    if (start >= end) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long step = FETCH_DATA_DURATION;
        if (step > remaining) {
            step = remaining;
        }
        long next = current + step;
        if (next <= current) { // overflow protection
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

