static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    try {
        // Parse year, month, day from YYYYMMDD
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Construct a LocalDate
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);

        // Calculate the starting day of the period
        int dayOfMonth = date.getDayOfMonth();
        int startDay = 1 + ((dayOfMonth - 1) / dayStep) * dayStep;

        // Create new date with adjusted day
        java.time.LocalDate newDate = date.withDayOfMonth(startDay);

        // Convert back to long YYYYMMDD
        return newDate.getYear() * 10000L
                + newDate.getMonthValue() * 100L
                + newDate.getDayOfMonth();
    } catch (java.time.DateTimeException e) {
        // If parsing fails, return the original value
        return timeBucket;
    }
}

static long compressTimeBucket(long timeBucket,int dayStep){
    if (timeBucket <= 0 || dayStep <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive and dayStep must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket / 100) % 100);
    int day = (int)(timeBucket % 100);

    // Validate month
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Invalid month in timeBucket");
    }

    // Determine last day of month
    int lastDay;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            lastDay = 31; break;
        case 4: case 6: case 9: case 11:
            lastDay = 30; break;
        case 2:
            boolean leap = (year % 400 == 0) || (year % 4 == 0 && year % 100 != 0);
            lastDay = leap ? 29 : 28; break;
        default:
            throw new IllegalArgumentException("Invalid month");
    }

    if (day < 1 || day > lastDay) {
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }

    int newDay = 1 + ((day - 1) / dayStep) * dayStep;

    return (long)year * 10000L + (long)month * 100L + newDay;
}

