        }

        if (day < 1 || day > daysInMonth) {
            throw new IllegalArgumentException("Invalid day in timeBucket");
        }

        int baselineDay = ((day - 1) / dayStep) * dayStep + 1;
        if (baselineDay > daysInMonth) {
            // If baseline exceeds month length, clamp to last day
            baselineDay = daysInMonth;
        }

        return year * 10000L + month * 100L + baselineDay;
    } catch (Exception e) {
        throw new IllegalArgumentException("Invalid timeBucket format", e);
    }
