        char ch = str.charAt(i);
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Surrogate pair represents a code point >= 0x10000
            size += 4;
            i += 2;
        } else {
            int cp = ch;
            if (cp <= 0x7F) {
                size += 1;
            } else if (cp <= 0x7FF) {
                size += 2;
            } else {
