    }
    final int strLen = str.length();
    if (index < 0 || len < 0 || index > strLen || index + len > strLen) {
        throw new IndexOutOfBoundsException(
                "index: " + index + ", len: " + len + ", string length: " + strLen);
    }
    int start = index;
    int end = index + len;
    int byteCount = 0;
    while (start < end) {
        char ch = str.charAt(start);
        if (Character.isHighSurrogate(ch)) {
            // Check if there's a low surrogate following
            if (start + 1 < end) {
                char low = str.charAt(start + 1);
                if (Character.isLowSurrogate(low)) {
                    int codePoint = Character.toCodePoint(ch, low);
                    // UTF-8 length for code point > 0xFFFF is 4 bytes
                    byteCount += 4;
                    start += 2; // skip both chars
                    continue;
                }
            }
            // Unpaired high surrogate: treat as replacement character (3 bytes)
            byteCount += 3;
            start++;
        } else if (Character.isLowSurrogate(ch)) {
            // Unpaired low surrogate: also treat as replacement character (3 bytes)
            byteCount += 3;
            start++;
        } else {
            int cp = ch;
            if (cp <= 0x7F) {
                byteCount += 1;
            } else if (cp <= 0x7FF) {
                byteCount += 2;
            } else {
                byteCount += 3;
            }
            start++;
        }
    }
    return byteCount;
}

