        throw new IndexOutOfBoundsException("index + length out of bounds: index=" + index
                + ", len=" + len + ", length=" + str.length());
    }

    int byteCount = 0;
    int i = index;
    try {
        while (i < end) {
            char ch = str.charAt(i);
            int codePoint;
            if (Character.isHighSurrogate(ch) && i + 1 < end
                    && Character.isLowSurrogate(str.charAt(i + 1))) {
                codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
                i += 2;
            } else {
                // Treat lone surrogate characters as a single code unit.
                codePoint = ch;
                i += 1;
            }

            if (codePoint <= 0x7F) {
                byteCount += 1;
            } else if (codePoint <= 0x7FF) {
                byteCount += 2;
            } else if (codePoint <= 0xFFFF) {
                byteCount += 3;
            } else {
                byteCount += 4;
            }
        }
    } catch (IndexOutOfBoundsException e) {
        // Unexpected subscript error – wrap and re‑throw as a more descriptive exception.
        throw new IndexOutOfBoundsException("Failed to compute UTF‑8 size: " + e.getMessage(), e);
    }
