    // Assumes the Edge class contains the following fields and methods:
    //   Vertex getEndpoint1(), getEndpoint2()
    //   Edge prevTreeEdge, nextTreeEdge
    //   Vertex.getFirstTreeEdge(), Vertex.getLastTreeEdge()
    //   Vertex.setFirstTreeEdge(Edge), Vertex.setLastTreeEdge(Edge)
