private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null && suffix == null) {
        return true;
    }
    if (str == null || suffix == null) {
        return false;
    }
    if (suffix.length() > str.length()) {
        return false;
    }
    if (ignoreCase) {
        int start = str.length() - suffix.length();
        return str.regionMatches(true, start, suffix, 0, suffix.length());
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, treat as matching
    if (str == null && suffix == null) {
        return true;
    }
    // If one is null only, they cannot match
    if (str == null || suffix == null) {
        return false;
    }

    int strLen = str.length();
    int suffixLen = suffix.length();

    // If suffix longer than str, cannot match
    if (suffixLen > strLen) {
        return false;
    }

    int startIndex = strLen - suffixLen;
    // regionMatches handles both case-sensitive and case-insensitive comparison
    return str.regionMatches(ignoreCase, startIndex, suffix, 0, suffixLen);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match by definition
    if (str == null && suffix == null) {
        return true;
    }
    // If only one is null, they cannot match
    if (str == null || suffix == null) {
        return false;
    }
    final int suffixLen = suffix.length();
    // If the suffix is longer than the string, it cannot match
    if (suffixLen > str.length()) {
        return false;
    }
    // Use regionMatches for case-insensitive comparison; otherwise use the native endsWith
    if (ignoreCase) {
        return str.regionMatches(true, str.length() - suffixLen, suffix, 0, suffixLen);
    } else {
        return str.endsWith(suffix);
    }
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // If both are null, consider it a match (mirroring behavior of startsWith in this library)
    if (str == null && suffix == null) {
        return true;
    }
    // If only one is null, cannot match
    if (str == null || suffix == null) {
        return false;
    }
    // Fast fail if suffix longer than source
    if (suffix.length() > str.length()) {
        return false;
    }
    // If ignoreCase is true, use regionMatches with ignoreCase flag
    if (ignoreCase) {
        int strOffset = str.length() - suffix.length();
        return str.regionMatches(true, strOffset, suffix, 0, suffix.length());
    }
    // Default case-sensitive comparison
    return str.endsWith(suffix);
}

private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null) {
        return suffix == null; // true if both are null
    }
    if (suffix == null) {
        return false;
    }
    int suffixLength = suffix.length();
    int strLength = str.length();
    if (suffixLength > strLength) {
        return false;
    }
    if (suffixLength == 0) {
        return true; // empty suffix is always matched
    }
    if (ignoreCase) {
        return str.regionMatches(true, strLength - suffixLength, suffix, 0, suffixLength);
    } else {
        return str.endsWith(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }

    // Split on '/', preserve empty parts
    String[] parts = rawPath.split("/", -1);
    int startIdx = 0;
    if (!parts[0].isEmpty()) {
        startIdx = 0; // relative path, include leading part
    } else {
        // absolute path: ignore leading empty segment
        startIdx = 1;
    }

    for (int i = startIdx; i < parts.length; i++) {
        String part = parts[i];
        if (decode) {
            try {
                part = java.net.URLDecoder.decode(part, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (IllegalArgumentException | java.io.UnsupportedEncodingException e) {
                // Treat decoding failure as malformed input
                throw new IllegalArgumentException("Invalid percent-encoding in path segment: "
                        + parts[i], e);
            }
        }
        segments.add(new PathSegmentImpl(part));
    }

    return segments;
}

