        String path;
        if (decode) {
            // getPath returns the decoded path
            path = u.getPath();
            if (path == null) {
                path = rawPath; // fallback, should not happen
            }
        } else {
            path = rawPath;
        }

        // Remove leading slash for absolute path components
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        // Split into segments (include empty segments if any)
        String[] parts = path.split("/", -1);
        for (String part : parts) {
            segments.add(new PathSegmentImpl(part));
        }
    } catch (Exception e) {
        // Wrap any unexpected exception into a runtime exception
        throw new RuntimeException("Failed to decode path segments", e);
    }
    return segments;
}

