public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI must not be null");
    }
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    int startIdx = 0;
    if (path.startsWith("/")) {
        // For absolute paths ignore the leading slash
        startIdx = 1;
    }
    // Split on '/' while preserving empty segments
    String relativePath = path.substring(startIdx);
    String[] parts = relativePath.isEmpty() ? new String[0] : relativePath.split("/", -1);
    for (String part : parts) {
        String decoded = part;
        if (decode && !part.isEmpty()) {
            try {
                decoded = java.net.URLDecoder.decode(part, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; ignore
            }
        }
        // Construct a PathSegmentImpl with both encoded and decoded representations
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    List<PathSegmentImpl> segments = new ArrayList<>();

    String rawPath = u.getRawPath();
    if (rawPath == null || rawPath.isEmpty()) {
        return segments;
    }

    String[] parts = rawPath.split("/");
    boolean skipFirst = rawPath.startsWith("/");

    for (int i = 0; i < parts.length; i++) {
        if (skipFirst && i == 0) {
            continue;
        }
        String part = parts[i];
        // Separate matrix parameters if present
        int idx = part.indexOf(';');
        String pathSegment = (idx >= 0) ? part.substring(0, idx) : part;

        if (decode) {
            try {
                pathSegment = java.net.URLDecoder.decode(pathSegment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // Treat any decoding exception as runtime
                throw new RuntimeException("Failed to decode URI component", e);
            }
        }

        // Create PathSegmentImpl with the decoded path segment.
        // If PathSegmentImpl has a constructor that accepts (String, Map), it will be chosen.
        // Otherwise, a constructor that accepts only (String) will be used.
        PathSegmentImpl ps;
        try {
            java.lang.reflect.Constructor<PathSegmentImpl> ctor = null;
            try {
                ctor = PathSegmentImpl.class.getDeclaredConstructor(String.class, java.util.Map.class);
                ps = ctor.newInstance(pathSegment, new java.util.HashMap<>());
            } catch (NoSuchMethodException e) {
                // Fall back to single-argument constructor
                ctor = PathSegmentImpl.class.getDeclaredConstructor(String.class);
                ps = ctor.newInstance(pathSegment);
            }
        } catch (Exception e) {
            // Fallback to single-argument constructor if all fails
            ps = new PathSegmentImpl(pathSegment);
        }
        segments.add(ps);
    }
    return segments;
}

