    if (fileIterator == null) {
        return null;
    }
    while (fileIterator.hasNext()) {
        File file = fileIterator.next();
        if (file == null) {
            continue;
        }
        try {
            return new FileInputStream(file);
        } catch (FileNotFoundException e) {
            // Skip this file and try the next one
            continue;
        } catch (SecurityException e) {
            // Skip this file and try the next one
            continue;
        }
    }
    return null;
}

