public InputStream next() throws IOException {
    // Make sure the iterator that keeps track of the files has been initialized.
    if (fileIterator == null) {
        throw new IllegalStateException("File iterator has not been initialized.");
    }

    // If there are no more files, return null as specified in the docs.
    if (!fileIterator.hasNext()) {
        return null;
    }

    // Retrieve the next file from the iterator.
    java.io.File file = fileIterator.next();
    if (file == null) {
        return null;
    }

    // Verify that the retrieved object is a readable regular file before attempting to open it.
    if (!file.isFile()) {
        throw new IOException("Expected a regular file but got: " + file);
    }
    if (!file.canRead()) {
        throw new IOException("File cannot be read: " + file);
    }

    // Return a FileInputStream for the file. The IOException can propagate to the caller.
    return new java.io.FileInputStream(file);
}

