private void pop(final String descriptor) {
    // Basic validation of the descriptor string
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor must not be null or empty");
    }

    int len = descriptor.length();
    int pos = 0;

    try {
        // Handle method descriptor (starts with '(')
        if (descriptor.charAt(0) == '(') {
            pos++; // Skip '('
            while (pos < len && descriptor.charAt(pos) != ')') {
                // Consume one argument type
                char c = descriptor.charAt(pos);
                if (c == '[') {
                    // Array type: consume all '[' characters
                    while (pos < len && descriptor.charAt(pos) == '[') {
                        pos++;
                    }
                    // Now process base type of the array
                    if (pos >= len) {
                        throw new IllegalArgumentException("Malformed array type in descriptor");
                    }
                    if (descriptor.charAt(pos) == 'L') {
                        // Object inside array
                        pos++; // Skip 'L'
                        while (pos < len && descriptor.charAt(pos) != ';') {
                            pos++;
                        }
                        if (pos >= len) {
                            throw new IllegalArgumentException("Unterminated object type in descriptor");
                        }
                        pos++; // Skip ';'
                    } else {
                        // Primitive type inside array
                        pos++; // Skip the primitive code
                    }
                } else if (c == 'L') {
                    // Object type
                    pos++; // Skip 'L'
                    while (pos < len && descriptor.charAt(pos) != ';') {
                        pos++;
                    }
                    if (pos >= len) {
                        throw new IllegalArgumentException("Unterminated object type in descriptor");
                    }
                    pos++; // Skip ';'
                } else {
                    // Primitive type
                    pos++; // Skip the single character code
                }

                // Pop one entry from the output frame stack for THIS argument type
                try {
                    outputFrameStack.pop();
                } catch (java.util.NoSuchElementException e) {
                    throw new IllegalStateException("Output frame stack underflow while popping argument types", e);
                }
            }

            // Validate closing parenthesis
            if (pos >= len || descriptor.charAt(pos) != ')') {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')' ");
            }
            // Return type is ignored for popping purposes; it may exist after ')'
        } else {
            // Single type descriptor
            char c = descriptor.charAt(pos);
            if (c == '[') {
                // Array type: consume all '[' characters
                while (pos < len && descriptor.charAt(pos) == '[') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Malformed array type in descriptor");
                }
                if (descriptor.charAt(pos) == 'L') {
                    // Object inside array
                    pos++; // Skip 'L'
                    while (pos < len && descriptor.charAt(pos) != ';') {
                        pos++;
                    }
                    if (pos >= len) {
                        throw new IllegalArgumentException("Unterminated object type in descriptor");
                    }
                    pos++; // Skip ';'
                } else {
                    // Primitive type inside array
                    pos++; // Skip the primitive code
                }
            } else if (c == 'L') {
                // Object type
                pos++; // Skip 'L'
                while (pos < len && descriptor.charAt(pos) != ';') {
                    pos++;
                }
                if (pos >= len) {
                    throw new IllegalArgumentException("Unterminated object type in descriptor");
                }
                pos++; // Skip ';'
            } else {
                // Primitive type
                pos++; // Skip the single character code
            }

            // Pop the single type from the output frame stack
            try {
                outputFrameStack.pop();
            } catch (java.util.NoSuchElementException e) {
                throw new IllegalStateException("Output frame stack underflow while popping type", e);
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Descriptor is malformed: " + descriptor, e);
    }
}

