private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }
    // Assume a field named outputFrameStack exists in the surrounding class.
    // It is a Deque<?> containing the abstract types to pop.
    final java.util.Deque<?> stack = outputFrameStack;
    int idx = 0;
    final int len = descriptor.length();

    // Helper to pop a type from the stack, checking for underflow.
    java.util.function.Consumer<Void> popFromStack = v -> {
        if (stack.isEmpty()) {
            throw new IllegalStateException("Underflow while popping abstract type");
        }
        stack.pop();
    };

    if (descriptor.charAt(0) == '(') { // method descriptor
        int end = descriptor.indexOf(')', idx);
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        idx = 1; // start after '('
        while (idx < end) {
            char c = descriptor.charAt(idx);
            if (c == 'L') { // object type
                int semicolon = descriptor.indexOf(';', idx);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid object type descriptor");
                }
                idx = semicolon + 1;
            } else if (c == '[') { // array type
                while (descriptor.charAt(idx) == '[') {
                    idx++;
                    if (idx >= len) {
                        throw new IllegalArgumentException("Invalid array type descriptor");
                    }
                }
                if (descriptor.charAt(idx) == 'L') {
                    int semicolon = descriptor.indexOf(';', idx);
                    if (semicolon == -1) {
                        throw new IllegalArgumentException("Invalid object type descriptor");
                    }
                    idx = semicolon + 1;
                } else { // primitive component
                    idx++;
                }
            } else { // primitive type
                idx++;
            }
            popFromStack.accept(null);
        }
        // Return type after ')' is ignored for popping
    } else { // type descriptor
        char c = descriptor.charAt(idx);
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', idx);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid object type descriptor");
            }
            idx = semicolon + 1;
        } else if (c == '[') {
            while (descriptor.charAt(idx) == '[') {
                idx++;
                if (idx >= len) {
                    throw new IllegalArgumentException("Invalid array type descriptor");
                }
            }
            if (descriptor.charAt(idx) == 'L') {
                int semicolon = descriptor.indexOf(';', idx);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid object type descriptor");
                }
                idx = semicolon + 1;
            } else {
                idx++;
            }
        } else { // primitive type
            idx++;
        }
        popFromStack.accept(null);
    }
}

