private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("size must be non-negative");
    }
    // Ensure the current buffer is not null.
    if (this.buf == null) {
        this.buf = new byte[(size > 0) ? size : 8];
        this.pos = 0;
        return;
    }
    int currentPos = this.pos;
    int newCap = currentPos + size;
    if (newCap > this.buf.length) {
        int oldLen = this.buf.length;
        int newLen = (oldLen << 1) + 1;
        if (newLen < newCap) {
            newLen = newCap;
        }
        byte[] newBuf = new byte[newLen];
        System.arraycopy(this.buf, 0, newBuf, 0, currentPos);
        this.buf = newBuf;
    }
}

