    }
    // If the first two characters are already uppercase, leaving the string unchanged
    if (name.length() > 1 
            && Character.isUpperCase(name.charAt(0))
            && Character.isUpperCase(name.charAt(1))){
        return name;
    }
    // Convert the first character to uppercase
