public static String capitalize(String name){
    try {
        if (name == null) return null;
        int len = name.length();
        if (len == 0) return "";
        if (len >= 2 && Character.isUpperCase(name.charAt(1))) {
            // second char is uppercase, leave string unchanged
            return name;
        }
        char first = Character.toUpperCase(name.charAt(0));
        if (len == 1) {
            return String.valueOf(first);
        }
        return first + name.substring(1);
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return null
        return null;
    }
}

