private void putAbstractTypes(final int start, final int end) {
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException("Invalid start or end indices: start=" + start + ", end=" + end + ", frameLength=" + currentFrame.length);
    }
    for (int i = start; i < end; i++) {
        final Object type = currentFrame[i];
        if (type == null) {
            throw new IllegalStateException("Abstract type at index " + i + " is null");
        }
        try {
            if (type instanceof AbstractType) {
                ((AbstractType) type).writeVerificationTypeInfo(stackMapTableEntries);
            } else {
                java.lang.reflect.Method m = type.getClass().getMethod("writeVerificationTypeInfo", java.util.List.class);
                m.invoke(type, stackMapTableEntries);
            }
        } catch (NoSuchMethodException e) {
            throw new RuntimeException("Abstract type does not expose writeVerificationTypeInfo(List) method", e);
        } catch (Exception e) {
            throw new RuntimeException("Failed to encode abstract type at index " + i, e);
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    try{
        if(currentFrame==null){
            throw new IllegalStateException("currentFrame is null");
        }
        if(end<start){
            return;
        }
        int length=java.lang.reflect.Array.getLength(currentFrame);
        if(start<0||end>length){
            throw new IndexOutOfBoundsException("start "+start+" or end "+end+" out of bounds for currentFrame length "+length);
        }
        for(int i=start;i<end;i++){
            Object type=java.lang.reflect.Array.get(currentFrame,i);
            int tag=getVerificationTag(type);
            stackMapTableEntries.add(tag);
            if(tag==7||tag==8){
                int index=getIndexFromType(type);
                stackMapTableEntries.add((index>>8)&0xFF);
                stackMapTableEntries.add(index&0xFF);
            }
        }
    }catch(Exception e){
        e.printStackTrace();
    }
}

