    }
    int frameSize = currentFrame.size();
    if (start < 0 || end > frameSize || start > end) {
        throw new IllegalArgumentException(
            String.format("Invalid indices: start=%d, end=%d, frameSize=%d", start, end, frameSize));
    }
    for (int i = start; i < end; i++) {
        Object frameElement = currentFrame.get(i);
        if (frameElement == null) {
            throw new IllegalStateException("Null type entry in currentFrame at index " + i);
        }
        try {
            writeVerificationTypeInfo(frameElement);
        } catch (Exception e) {
            throw new IllegalStateException(
                "Failed to write verification type info for element at index " + i, e);
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is not initialized");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is not initialized");
    }
    final int length = currentFrame.length;
    if (start < 0 || end < start || end > length) {
        throw new IndexOutOfBoundsException(
                "start=" + start + ", end=" + end + ", frame length=" + length);
    }
    for (int i = start; i < end; i++) {
        int typeTag = currentFrame[i];
        // The JVMS defines tags 0-8 for verification_type_info
        if (typeTag < 0 || typeTag > 8) {
            throw new IllegalArgumentException(
                    "Unsupported verification type tag at index " + i + ": " + typeTag);
        }
        // Append the tag byte
        stackMapTableEntries.add((byte) typeTag);
        // For OBJECT (tag 7) and UNINITIALIZED (tag 8) the caller is expected
        // to provide the additional two-byte data (cp_info index or offset)
        // after invoking this method, because that information is not available
        // solely from the abstract type descriptor.
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    // Read the entire stream into a temporary buffer
    ByteArrayOutputStream bout = new ByteArrayOutputStream();
    byte[] chunk = new byte[8192];
    int read;
    while ((read = in.read(chunk)) != -1) {
        bout.write(chunk, 0, read);
    }
    // Replace the existing buffer with the new data and reset pointer
    this.buffer = bout.toByteArray();
    this.readPointer = 0;
}

