public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if ((candidate & 1) == 0) {
        candidate++; // make it odd
    }
    while (true) {
        boolean isPrime = true;
        if (candidate <= 3) {
            if (candidate >= 2) {
                return candidate;
            }
        } else {
            if ((candidate & 1) == 0 || candidate % 3 == 0) {
                isPrime = false;
            } else {
                for (int i = 5; (long) i * i <= candidate; i += 6) {
                    if (candidate % i == 0 || candidate % (i + 2) == 0) {
                        isPrime = false;
                        break;
                    }
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        candidate += 2; // skip even numbers
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("desiredCapacity must be > 0");
    }
    if (desiredCapacity == 1) {
        return 2;
    }

    int candidate = desiredCapacity;
    if (candidate > 2 && (candidate & 1) == 0) {
        candidate++; // make odd
    }

    int maxCandidate = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        long limitLong = (long) desiredCapacity * 111L / 100L + 5; // 1.11 * desiredCapacity + small padding
        if (limitLong < Integer.MAX_VALUE) {
            maxCandidate = (int) limitLong;
        }
    }

    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }

        // Increment to the next candidate
        if (candidate == 2) {
            candidate = 3;
        } else {
            candidate += 2; // only check odd numbers
        }

        if (candidate < 0) { // overflow
            throw new IllegalArgumentException("desiredCapacity too large");
        }
        if (desiredCapacity >= 1000 && candidate > maxCandidate) {
            // No prime found within 11% – return the first prime found anyway
            return candidate;
        }
    }
}

