public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }
    // When desiredCapacity is very large, the largest prime ≤ Integer.MAX_VALUE is Integer.MAX_VALUE itself
    if (desiredCapacity >= Integer.MAX_VALUE - 6) {
        return Integer.MAX_VALUE;
    }
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (true) {
        boolean isPrime;
        if (candidate <= 1) {
            isPrime = false;
        } else if (candidate <= 3) {
            isPrime = true;
        } else if (candidate % 2 == 0 || candidate % 3 == 0) {
            isPrime = false;
        } else {
            int limit = (int) Math.sqrt(candidate);
            isPrime = true;
            for (int i = 5; i <= limit; i += 6) {
                if (candidate % i == 0 || candidate % (i + 2) == 0) {
                    isPrime = false;
                    break;
                }
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Guard against overflow
        if (candidate > Integer.MAX_VALUE - 2) {
            return Integer.MAX_VALUE;
        }
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity) {
    // Handle non-positive capacities by returning the smallest prime
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Avoid overflow when desiredCapacity is close to Integer.MAX_VALUE
    if (desiredCapacity > Integer.MAX_VALUE - 10) {
        throw new IllegalArgumentException("Desired capacity too large to find next prime: " + desiredCapacity);
    }

    // Start from the desired capacity, ensuring it is odd (except for 2)
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }

    // Upper bound for searching within 11% if desired >= 1000
    int upperBound = candidate;
    if (desiredCapacity >= 1000) {
        long ub = (long) candidate + (long) candidate / 10 + 1; // 10% + 1
        // limit to Integer.MAX_VALUE
        if (ub > Integer.MAX_VALUE) {
            ub = Integer.MAX_VALUE;
        }
        upperBound = (int) ub;
    }

    while (candidate <= upperBound) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2; // skip even numbers
        // Avoid potential overflow
        if (candidate <= 0) {
            break;
        }
    }

    // If not found within bound, continue searching until we find a prime
    candidate = upperBound | 1; // make odd
    while (candidate > 0) { // loop until overflow wraps to negative
        if (isPrime(candidate)) {
            return candidate;
        }
        if (candidate > Integer.MAX_VALUE - 2) {
            break; // cannot increment further without overflow
        }
        candidate += 2;
    }

    // As a last resort, return Integer.MAX_VALUE if no prime found (highly unlikely)
    throw new IllegalStateException("Unable to find next prime for capacity: " + desiredCapacity);
}

