        }
        len = (len << 8) | (b & 0xFF);
    }
    if (len < 0) {
        throw new IOException("Negative string length: " + len);
    }
    byte[] bytes = new byte[len];
    int read = 0;
    while (read < len) {
        int r = in.read(bytes, read, len - read);
        if (r == -1) {
            throw new IOException("Unexpected end of stream while reading string data");
        }
        read += r;
    }
    try {
        return new String(bytes, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        // This should never happen for UTF-8
        throw new IOException("UTF-8 encoding not supported", e);
    }
}

