        int oldLength = java.lang.reflect.Array.getLength(array);
        int newLength = oldLength + 1;
        Object newArray = java.lang.reflect.Array.newInstance(componentType, newLength);
        for (int i = 0; i < oldLength; i++) {
            java.lang.reflect.Array.set(newArray, i, java.lang.reflect.Array.get(array, i));
        }
        return newArray;
    } catch (IllegalArgumentException | IllegalAccessException e) {
        throw new RuntimeException("Failed to grow array: " + e.getMessage(), e);
    }
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // If the input array is null, create an array of size 1 using the provided component type.
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new NullPointerException("newArrayComponentType must not be null when array is null");
        }
        return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
    }

    // Ensure the provided object is actually an array.
    final Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("Provided object is not an array");
    }

    // Determine the component type of the existing array.
    final Class<?> componentType = arrayClass.getComponentType();

    // Validate that the array length can be increased by one without integer overflow.
    final int oldLength = java.lang.reflect.Array.getLength(array);
    if (oldLength == Integer.MAX_VALUE) {
        throw new RuntimeException("Array is already at maximum size; cannot grow");
    }

    // Create a new array with one additional element.
    final Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);

    // Copy existing elements into the new array.
    System.arraycopy(array, 0, newArray, 0, oldLength);

    // The last element is left at its default value (null for objects, 0/false for primitives).
    return newArray;
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    try {
        if (array == null) {
            if (newArrayComponentType == null) {
                throw new IllegalArgumentException("newArrayComponentType must not be null when array is null");
            }
            return java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
        }
        Class<?> arrayClass = array.getClass();
        if (!arrayClass.isArray() || arrayClass.getComponentType() == null) {
            throw new IllegalArgumentException("Provided object is not an array");
        }
        int oldLen = java.lang.reflect.Array.getLength(array);
        Class<?> compType = arrayClass.getComponentType();
        Object newArray = java.lang.reflect.Array.newInstance(compType, oldLen + 1);
        System.arraycopy(array, 0, newArray, 0, oldLen);
        return newArray;
    } catch (RuntimeException e) {
        throw e; // rethrow unchecked exceptions
    } catch (Exception e) {
        throw new RuntimeException(e);
    }
}

