private static boolean isAllZeros(String s) {
    if (s == null) {
        return true;
    }
    int len = s.length();
    int i = 0;
    // Skip leading whitespace
    while (i < len && Character.isWhitespace(s.charAt(i))) {
        i++;
    }
    if (i == len) {
        // String contains only whitespace
        return true;
    }
    // Skip optional sign
    char firstChar = s.charAt(i);
    if (firstChar == '+' || firstChar == '-') {
        i++;
    }
    boolean hasNonZero = false;
    for (; i < len; i++) {
        char c = s.charAt(i);
        if (Character.isWhitespace(c) || c == '.') {
            continue; // ignore whitespace and decimal point
        }
        if (c == 'e' || c == 'E') {
            // exponent part – ignore the rest
            break;
        }
        if (!Character.isDigit(c)) {
            // Contains non-numeric character → not all zeros
            return false;
        }
        if (c != '0') {
            hasNonZero = true;
        }
    }
    return !hasNonZero;
}

