        return true;
    }
    try {
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) != '0') {
                return false;
            }
        }
        return true;
    } catch (Exception e) {
        // In case of unexpected character or internal error, treat as not all zeros
        return false;
    }
}

