protected int removeUnusedNodes(){
    int removed = 0;
    try {
        if (root == null) {
            return removed;
        }
        if (!root.isActive()) {
            root = null;
            removed++;
            return removed;
        }
        LinkedList<Category> stack = new LinkedList<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            Category node = stack.pop();
            List<Category> children = node.getChildren();
            if (children == null) continue;
            for (Iterator<Category> it = children.iterator(); it.hasNext();) {
                Category child = it.next();
                if (!child.isActive()) {
                    it.remove();
                    removed++;
                } else {
                    stack.push(child);
                }
            }
        }
    } catch (Exception e) {
        return 0;
    }
    return removed;
}

protected int removeUnusedNodes() {
    try {
        // Assume the tree has a root node accessible via 'root' field.
        if (this.root == null) {
            return 0;
        }
        return removeUnusedNodesRecursive(this.root);
    } catch (Exception e) {
        // Log the exception if any logging mechanism is available.
        e.printStackTrace();
        return 0;
    }
}

protected int removeUnusedNodes() {
    // Inner helper class to process the tree recursively
    class Processor {
        int removedCount = 0;

        void process(Category node) {
            if (node == null) {
                return;
            }
            java.util.List<Category> children = node.getChildren();
            if (children == null) {
                return;
            }
            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (child == null) {
                    continue;
                }
                if (!child.isActive()) {
                    // Count all nodes in the inactive subtree
                    removedCount += countSubtree(child);
                    // Remove the inactive child from the list
                    it.remove();
                } else {
                    // Recurse into active child
                    process(child);
                }
            }
        }

        int countSubtree(Category node) {
            int count = 1; // count this node
            java.util.List<Category> subChildren = node.getChildren();
            if (subChildren != null) {
                for (Category c : subChildren) {
                    count += countSubtree(c);
                }
            }
            return count;
        }
    }

    try {
        if (root == null) {
            return 0;
        }
        Processor processor = new Processor();
        processor.process(root);
        return processor.removedCount;
    } catch (Exception e) {
        // Exception handling: could log the error
        return 0;
    }
}

protected int removeUnusedNodes() {
    if (categories == null) {
        return 0;
    }

    int removedCount = 0;
    Iterator<Category> it = categories.iterator();

    while (it.hasNext()) {
        Category cat = it.next();
        removedCount += removeRecursive(cat, it);
    }

    return removedCount;
}

protected int removeUnusedNodes() {
    try {
        if (root == null) {
            return 0;
        }
        java.util.concurrent.atomic.AtomicInteger removedCount = new java.util.concurrent.atomic.AtomicInteger(0);
        java.util.function.Consumer<Category> removeRecursively = new java.util.function.Consumer<Category>() {
            @Override
            public void accept(Category node) {
                if (node == null) {
                    return;
                }
                java.util.List<Category> subcats = node.getSubcategories();
                if (subcats == null || subcats.isEmpty()) {
                    return;
                }
                java.util.Iterator<Category> it = subcats.iterator();
                while (it.hasNext()) {
                    Category child = it.next();
                    if (!child.isActive()) {
                        it.remove();
                        removedCount.incrementAndGet();
                    } else {
                        accept(child);
                    }
                }
            }
        };
        removeRecursively.accept(root);
        return removedCount.get();
    } catch (Exception e) {
        // Log the exception if needed and return 0
        return 0;
    }
}

