public static boolean toBoolean(String value, boolean dEfault) {
    if (value == null) {
        return dEfault;
    }
    String trimmed = value.trim();
    if (trimmed.length() == 0) {
        return dEfault;
    }
    String lower = trimmed.toLowerCase(Locale.ENGLISH);
    switch (lower) {
        case "true":
            return true;
        case "false":
            return false;
        default:
            return dEfault;
    }
}

