    if (constantPoolEntryIndex <= 0 || constantPoolEntryIndex >= constantPoolInfoOffsets.length) {
        throw new IllegalArgumentException("Invalid constant pool index: " + constantPoolEntryIndex);
    }
    final int offset = constantPoolInfoOffsets[constantPoolEntryIndex];
    if (offset < 0 || offset + 3 > classFileBuffer.length) {
        throw new IllegalArgumentException("Invalid constant pool entry offset for index: " + constantPoolEntryIndex);
    }
