    final int length = ((classFileBuffer[offset + 1] & 0xFF) << 8) |
                       (classFileBuffer[offset + 2] & 0xFF);
    if (length < 0) {
        throw new IllegalArgumentException("Negative UTF-8 length at index " + constantPoolEntryIndex);
    }
    final int byteStart = offset + 3;
    final int byteEnd = byteStart + length;
    if (byteEnd > classFileBuffer.length) {
        throw new IllegalArgumentException("UTF-8 string at index " + constantPoolEntryIndex + " exceeds class file size");
    }
    // Ensure charBuffer is large enough
    if (charBuffer == null || charBuffer.length < length) {
        throw new IllegalArgumentException("charBuffer too small to hold UTF-8 entry at index " + constantPoolEntryIndex);
    }
    // Decode the bytes into a Java String using UTF-8
    final String utfString = new String(classFileBuffer, byteStart, length, java.nio.charset.StandardCharsets.UTF_8);
    // Copy the resulting characters into the supplied buffer
    final int actualLength = utfString.length();
    if (actualLength > charBuffer.length) {
        throw new IllegalStateException("Decoded UTF-8 string length exceeds buffer capacity");
    }
    utfString.getChars(0, actualLength, charBuffer, 0);
    return utfString;
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        // Validate the constant pool entry index
        if (constantPoolEntryIndex <= 0) {
            throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
        }

        // The constant pool count is stored at bytes 8 and 9 (big-endian)
        final int constantPoolCount = ((classFileBuffer[8] & 0xFF) << 8) | (classFileBuffer[9] & 0xFF);
        if (constantPoolEntryIndex >= constantPoolCount) {
            throw new IllegalArgumentException("constantPoolEntryIndex out of range");
        }

        // Start after magic (4), minor (2), major (2), constant_pool_count (2) => offset = 10
        int offset = 10;
        for (int i = 1; i < constantPoolEntryIndex; i++) {
            int tag = classFileBuffer[offset] & 0xFF;
            offset++; // move past tag
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + length; // length bytes + the length field itself
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    // These entries take up two slots in the constant pool
                    i++;
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                case 12: // CONSTANT_NameAndType
                case 15: // CONSTANT_MethodHandle
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 17: // CONSTANT_Dynamic
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                case 19: // CONSTANT_Module
                case 20: // CONSTANT_Package
                    offset += 2;
                    break;
                default:
                    throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
            }
        }

        // Now offset points to the tag of the target CONSTANT_Utf8 entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Expected CONSTANT_Utf8 at index " + constantPoolEntryIndex);
        }

        // Length of the UTF-8 encoded string
        int length = ((classFileBuffer[offset + 1] & 0xFF) << 8)
                   | (classFileBuffer[offset + 2] & 0xFF);

        // Validate charBuffer size (not strictly necessary but follows the contract)
        if (charBuffer == null || charBuffer.length < length) {
            throw new IllegalArgumentException(
                "charBuffer is null or not large enough to hold the UTF-8 string");
        }

        // Decode UTF-8 bytes into a String. We avoid allocating a temporary byte array,
        // instead using the String constructor that accepts a byte array slice.
        // The constructor will interpret the bytes as UTF-8 by default.
        String result = new String(classFileBuffer, offset + 3, length,
                                   java.nio.charset.StandardCharsets.UTF_8);

        // Optionally, copy the characters into the provided char buffer if desired.
        // This step is skipped because the method contract only requires returning
        // the String; the buffer can be filled later by the caller if needed.
        return result;
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Malformed classFileBuffer or invalid index", e);
    } catch (Exception e) {
        throw new IllegalArgumentException("Unexpected error while reading UTF-8 constant pool entry", e);
    }
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    if (constantPoolEntryIndex <= 0){
        throw new IllegalArgumentException("constantPoolEntryIndex must be > 0");
    }
    if (classFileBuffer == null){
        throw new IllegalStateException("classFileBuffer is null");
    }
    final byte[] buffer = classFileBuffer;
    // Skip magic (4 bytes) + minor_version (2) + major_version (2) + constant_pool_count (2)
    int offset = 4 + 2 + 2;
    if (offset + 2 > buffer.length){
        throw new IllegalStateException("Truncated class file");
    }
    int cpCount = ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
    offset += 2;
    if (constantPoolEntryIndex >= cpCount){
        throw new IllegalArgumentException("constantPoolEntryIndex out of range");
    }
    // Scan constant pool entries to reach the desired index
    int currentIndex = 1;
    while (currentIndex < constantPoolEntryIndex){
        if (offset >= buffer.length){
            throw new IllegalStateException("Truncated constant pool");
        }
        int tag = buffer[offset] & 0xFF;
        offset++;
        switch (tag) {
            case 1: // CONSTANT_Utf8
                if (offset + 2 > buffer.length){
                    throw new IllegalStateException("Truncated UTF8 length");
                }
                int len = ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
                offset += 2 + len;
                break;
            case 3: case 4: // CONSTANT_Integer, CONSTANT_Float
                offset += 4;
                break;
            case 5: case 6: // CONSTANT_Long, CONSTANT_Double (take two indices)
                offset += 8;
                currentIndex++; // skip the unused entry
                break;
            case 7: case 8: // CONSTANT_Class, CONSTANT_String
            case 9: case 10: // CONSTANT_Fieldref, CONSTANT_Methodref
            case 11: case 12: // CONSTANT_InterfaceMethodref, CONSTANT_NameAndType
            case 15: // CONSTANT_MethodHandle
            case 16: // CONSTANT_MethodType
            case 18: // CONSTANT_InvokeDynamic
                offset += 2;
                break;
            default:
                throw new IllegalStateException("Unknown constant pool tag: " + tag);
        }
        currentIndex++;
    }
    // Now read the target CONSTANT_Utf8 entry
    if (offset + 3 > buffer.length){
        throw new IllegalStateException("Truncated CONSTANT_Utf8 entry");
    }
    int tag = buffer[offset] & 0xFF;
    if (tag != 1){
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not CONSTANT_Utf8");
    }
    offset++; // skip tag
    int utfLen = ((buffer[offset] & 0xFF) << 8) | (buffer[offset + 1] & 0xFF);
    offset += 2;
    if (utfLen > charBuffer.length){
        throw new IllegalArgumentException("Provided char buffer too small for UTF-8 string of length " + utfLen);
    }
    int end = offset + utfLen;
    if (end > buffer.length){
        throw new IllegalStateException("Truncated UTF-8 string data");
    }
    int charPos = 0;
    while (offset < end){
        int b = buffer[offset++] & 0xFF;
        if ((b & 0x80) == 0){ // 1-byte ASCII
            charBuffer[charPos++] = (char)b;
        } else if ((b & 0xE0) == 0xC0){ // 2-byte
            int b2 = buffer[offset++] & 0xFF;
            charBuffer[charPos++] = (char)((b & 0x1F) << 6 | (b2 & 0x3F));
        } else if ((b & 0xF0) == 0xE0){ // 3-byte
            int b2 = buffer[offset++] & 0xFF;
            int b3 = buffer[offset++] & 0xFF;
            charBuffer[charPos++] = (char)((b & 0x0F) << 12 | (b2 & 0x3F) << 6 | (b3 & 0x3F));
        } else if ((b & 0xF8) == 0xF0){ // 4-byte -> surrogate pair
            int b2 = buffer[offset++] & 0xFF;
            int b3 = buffer[offset++] & 0xFF;
            int b4 = buffer[offset++] & 0xFF;
            int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) |
                            ((b3 & 0x3F) << 6) | (b4 & 0x3F);
            codePoint -= 0x10000;
            charBuffer[charPos++] = (char)(0xD800 + (codePoint >> 10));
            charBuffer[charPos++] = (char)(0xDC00 + (codePoint & 0x3FF));
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 encoding encountered");
        }
    }
    return new String(charBuffer, 0, charPos);
}

final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Validate input indices
    if (classFileBuffer == null) throw new IllegalStateException("Class file buffer is not initialized");
    if (constantPoolEntryIndex <= 0) throw new IllegalArgumentException("Constant pool indices start at 1");

    try {
        int offset = 10; // magic(4) + minor(2) + major(2) + constant_pool_count(2)
        if (offset + 2 > classFileBuffer.length) throw new IllegalStateException("Malformed class file");

        // Read constant_pool_count (u2)
        int cpCount = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2;

        for (int i = 1; i < cpCount; i++) {
            if (offset >= classFileBuffer.length) throw new IllegalStateException("Malformed constant pool");

            int tag = classFileBuffer[offset] & 0xFF;
            offset++;

            // If we have reached the desired entry
            if (i == constantPoolEntryIndex) {
                if (tag != 1) throw new IllegalArgumentException("Requested entry is not a CONSTANT_Utf8");
                if (offset + 2 > classFileBuffer.length) throw new IllegalStateException("Malformed Utf8 entry");

                int length = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                offset += 2;

                if (offset + length > classFileBuffer.length) throw new IllegalStateException("Malformed Utf8 data");

                // Decode the UTF-8 bytes
                String decoded = new String(classFileBuffer, offset, length, java.nio.charset.StandardCharsets.UTF_8);

                // Fill provided char buffer (if large enough)
                int charCount = decoded.length();
                if (charBuffer.length < charCount) throw new IllegalArgumentException("Provided char buffer is not large enough");

                decoded.getChars(0, charCount, charBuffer, 0);
                return new String(charBuffer, 0, charCount);
            }

            // Skip over this entry to position for the next
            switch (tag) {
                case 1: // CONSTANT_Utf8
                    if (offset + 2 > classFileBuffer.length) throw new IllegalStateException("Malformed Utf8 entry");
                    int skipLen = ((classFileBuffer[offset] & 0xFF) << 8) | (classFileBuffer[offset + 1] & 0xFF);
                    offset += 2 + skipLen;
                    break;
                case 3: // CONSTANT_Integer
                case 4: // CONSTANT_Float
                case 9: // CONSTANT_Fieldref
                case 10: // CONSTANT_Methodref
                case 11: // CONSTANT_InterfaceMethodref
                case 12: // CONSTANT_NameAndType
                    offset += 4;
                    break;
                case 5: // CONSTANT_Long
                case 6: // CONSTANT_Double
                    offset += 8;
                    i++; // these occupy two cp indices
                    break;
                case 7: // CONSTANT_Class
                case 8: // CONSTANT_String
                    offset += 2;
                    break;
                case 15: // CONSTANT_MethodHandle
                    offset += 3;
                    break;
                case 16: // CONSTANT_MethodType
                    offset += 2;
                    break;
                case 18: // CONSTANT_InvokeDynamic
                    offset += 4;
                    break;
                default:
                    throw new IllegalStateException("Unknown constant pool tag: " + tag);
            }
        }

        throw new IllegalArgumentException("Constant pool entry index out of range");
    } catch (RuntimeException e) {
        throw new RuntimeException("Failed to read CONSTANT_Utf8 entry at index " + constantPoolEntryIndex, e);
    }
