            }
            if (offset > classFileBuffer.length) {
                throw new IllegalArgumentException("class file truncated while parsing constant pool");
            }
        }

        // Now offset points at the desired entry
        int tag = classFileBuffer[offset] & 0xFF;
        if (tag != 1) {
            throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex
                    + " is not a CONSTANT_Utf8 (tag=" + tag + ')');
        }
        offset++; // move past tag
        if (offset + 2 > classFileBuffer.length) {
            throw new IllegalArgumentException("class file truncated before length field");
        }
        int length = ((classFileBuffer[offset] & 0xFF) << 8)
                | (classFileBuffer[offset + 1] & 0xFF);
        offset += 2; // point to string bytes
        if (offset + length > classFileBuffer.length) {
            throw new IllegalArgumentException("class file truncated before string data");
        }
        // Decode UTF-8
        String utfStr = new String(classFileBuffer, offset, length, java.nio.charset.StandardCharsets.UTF_8);
        if (charBuffer.length < utfStr.length()) {
