public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("Factorial is undefined for negative integers");
    }
    if (n > 20) { // 20! is the largest factorial that fits in a signed 64‑bit long
        throw new IllegalArgumentException("Result would overflow for n = " + n);
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

public static long factorial(int n){
    if (n < 0) {
        throw new IllegalArgumentException("Factorial is undefined for negative numbers: " + n);
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (result > Long.MAX_VALUE / i) {
            throw new ArithmeticException("Long overflow for factorial of " + n);
        }
        result *= i;
    }
    return result;
}

