    if (n < 0) {
        throw new IllegalArgumentException("Negative input not allowed");
    }
    long result = 1L;
    for (int i = 2; i <= n; i++) {
        if (Long.MAX_VALUE / result < i) {
            throw new ArithmeticException("Result exceeds long range");
        }
        result *= i;
    }
    return result;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Initialize a circulator starting at the specified node and direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    Node current = circ.getNode();

    // Iterate around the outer face until we reach the stop node or find a node
    // satisfying the predicate. A safety counter protects against accidental
    // infinite loops if the graph is malformed.
    int safety = 0;
    final int MAX_ITERATIONS = 10000;
    while (!current.equals(stop) && !predicate.test(current)) {
        circ.next();                     // advance to the next node along the outer face
        current = circ.getNode();        // fetch the new current node
        if (++safety > MAX_ITERATIONS) {
            break;                       // give up after too many iterations
        }
    }

    return circ;   // returns a circulator pointing at the matched node or at the stop node
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Node current = start;
    try {
        java.lang.reflect.Method nextMethod = Node.class.getDeclaredMethod("getNextOnOuterFace", int.class);
        do {
            if (predicate.test(current) || current == stop) {
                return new OuterFaceCirculator(current, dir);
            }
            current = (Node) nextMethod.invoke(current, dir);
            if (current == null) {
                break;
            }
        } while (current != start);
    } catch (Exception ignored) {
        // Either the method doesn't exist or an invocation error occurred; fall back to stop node.
    }
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    Objects.requireNonNull(predicate, "predicate must not be null");
    Objects.requireNonNull(start,    "start must not be null");
    Objects.requireNonNull(stop,     "stop must not be null");
    try {
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
        while (true) {
            Node current = circ.current();   // assume method returning the node at the circulator
            if (predicate.test(current)) {
                return circ;
            }
            if (current.equals(stop)) {
                break;
            }
            circ.next();     // advance to next node on the outer face
        }
        return circ;
    } catch (Exception e) {
        throw new RuntimeException("Failed to find node on outer face", e);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }
    Set<Node> visited = new java.util.HashSet<>();
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    while (true) {
        Node node = circ.getNode();
        if (predicate.test(node)) {
            return circ;
        }
        if (node.equals(stop)) {
            return circ;
        }
        if (!visited.add(node)) {
            throw new IllegalStateException("Failed to find predicate or stop node on outer face (possible infinite loop)");
        }
        circ = dir >= 0 ? circ.next() : circ.prev();
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Validate parameters
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node cannot be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node cannot be null");
    }

    // Create an OuterFaceCirculator starting from 'start'
    OuterFaceCirculator circulator;
    try {
        circulator = new OuterFaceCirculator(start, dir);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to initialize OuterFaceCirculator", e);
    }

    // If the start node is the stop node, return immediately
    if (start.equals(stop)) {
        return circulator;
    }

    // Iterate around the outer face until we either find a matching node or hit the stop node
    while (true) {
        Node currentNode = circulator.getNode(); // Assume getNode() returns the current node
        boolean satisfies;
        try {
            satisfies = predicate.test(currentNode);
        } catch (Exception e) {
            throw new IllegalStateException("Predicate evaluation failed", e);
        }

        if (satisfies) {
            return circulator;
        }

        // Move to the next node in the specified direction
        circulator.next(); // Assume next() advances the circulator

        // If after moving we are at the stop node, break out of the loop
        if (circulator.getNode().equals(stop)) {
            break;
        }
    }

    // Return the circulator positioned at the stop node
    return circulator;
}

