        deletions.add(cp);
        i += Character.charCount(cp);
    }

    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); ) {
        int cp = inString.codePointAt(i);
        if (!deletions.contains(cp)) {
            sb.appendCodePoint(cp);
        }
        i += Character.charCount(cp);
    }
    return sb.toString();
}

