        }
        pos = 0;
        count = n;
    }
    return buffer[pos++];
}

public byte readByte() throws IOException {
    // If the current position has reached the end of the buffer, refill it
    if (pos >= limit) {
        if (buf == null || buf.length == 0) {
            throw new IOException("Buffer is not initialized");
        }
        if (in == null) {
