        }
        int bytesRead = in.read(buf);
        if (bytesRead == -1) {
            throw new EOFException("End of stream reached");
        }
        pos = 0;
        limit = bytesRead;
    }
    // Return the next byte and advance the position
    return buf[pos++];
}

