@Override public Action inspect(AtmosphereResource r) {
    if (r == null) {
        throw new IllegalArgumentException("AtmosphereResource cannot be null");
    }
    try {
        AtmosphereResource.TRANSPORT transport = r.getTransport();
        if (transport != null && transport != AtmosphereResource.TRANSPORT.WEBSOCKET) {
            // Suspend for transports that support traditional (e.g., HTTP, SSE) long‑polling
            r.suspend();
        }
    } catch (Throwable t) {
        // Wrap and rethrow to avoid swallowing errors silently
        throw new RuntimeException("Failed to suspend AtmosphereResource", t);
    }
    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r) {
    // If the resource or its transport information is unavailable, just continue
    if (r == null) {
        return Action.CONTINUE;
    }

    try {
        // Determine the transport type
        Object transportObj = r.getTransport();
        if (transportObj != null) {
            // Convert to String (works for enum or String transports)
            String transport = transportObj.toString();
            // Do not suspend WebSocket transports as they keep the connection open
            if (!"WEBSOCKET".equalsIgnoreCase(transport)) {
                // Suspend the resource to allow asynchronous responses
                r.suspend();
            }
        } else {
            // If transport info is missing, suspend by default
            r.suspend();
        }
    } catch (Exception e) {
        // Suppress any exception and continue; logging could be added if desired
    }

    return Action.CONTINUE;
}

