@Override
public Action inspect(AtmosphereResource r) {
    try {
        if (r != null) {
            // Attempt to retrieve the transport type.  Most implementations provide a
            // getTransport() method that returns a String such as "websocket", "long-polling",
            // etc.  If the transport is anything other than a WebSocket, we suspend the
            // resource to trigger the Atmosphere suspend/resume logic.
            String transport = r.getTransport();
            if (transport != null && !transport.equalsIgnoreCase("websocket")) {
                r.suspend();
            }
        }
    } catch (Exception e) {
        // Preserve the exception for debugging but do not interrupt the filter chain.
        // In a real application you might log the exception here.
    }
    return Action.CONTINUE;
}

@Override
public Action inspect(AtmosphereResource r) {
    try {
        if (r == null) {
            return Action.CONTINUE;
        }
        Object transport = r.getTransport();
        // Suspend based on transport value
        if ("HTTP".equalsIgnoreCase(String.valueOf(transport))) {
            // Suspend HTTP requests (default timeout of 20 seconds)
            r.suspend(20000L);
        } else {
            // For other transports (e.g., WebSocket, SSE) suspend indefinitely
            r.suspend(0L);
        }
    } catch (Throwable t) {
        // Suppress any runtime exception to continue processing
    }
    return Action.CONTINUE;
}

