            return;
        }

        // Obtain the source bucket and ensure the destination bucket exists
        Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
        if (sourceBucket == null || sourceBucket.isEmpty()) {
            // Nothing to move, just ensure bucket 0 exists
            if (bucketsByLabel.get(0) == null) {
                bucketsByLabel.set(0, new java.util.HashSet<>());
            }
            return;
        }

        if (bucketsByLabel.get(0) == null) {
            bucketsByLabel.set(0, new java.util.HashSet<>());
        }
        Set<Integer> destinationBucket = bucketsByLabel.get(0);

        // Move all vertices
        destinationBucket.addAll(sourceBucket);
        for (Integer vertex : sourceBucket) {
            if (vertex != null && vertex >= 0 && vertex < labels.size()) {
                labels.set(vertex, 0);
            }
        }

        // Clear the source bucket
        sourceBucket.clear();
    } catch (Exception e) {
        // Wrap any unexpected exception to provide context
        throw new RuntimeException("Failed to reload buckets for minLabel=" + minLabel, e);
    }
}

