    if (sub.isEmpty()) {
        return 0;
    }
    int count = 0;
    int index = 0;
    int subLen = sub.length();
    while ((index = str.indexOf(sub, index)) != -1) {
        count++;
        index += subLen;
    }
    return count;
}

