protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new IllegalArgumentException("buffer must not be null");
    }
    // Ensure fieldName is non‑null to avoid NPE
    if (fieldName == null) {
        fieldName = "";
    }

    try {
        // If array is null, represent it explicitly
        if (array == null) {
            if (!fieldName.isEmpty()) {
                buffer.append(fieldName).append(" = ");
            }
            buffer.append("<null>");
            return;
        }

        // Append field name only if it is meaningful
        if (!fieldName.isEmpty()) {
            buffer.append(fieldName).append(" = ");
        }

        buffer.append('[');
        for (int i = 0; i < array.length; i++) {
            // Convert byte to unsigned hex string
            buffer.append(String.format("%02X", array[i] & 0xFF));
            if (i < array.length - 1) {
                buffer.append(", ");
            }
        }
        buffer.append(']');
    } catch (Exception e) {
        // In case of any unexpected error, fall back to a safe representation
        buffer.append(fieldName).append(" = <error: ")
              .append(e.getClass().getSimpleName())
              .append(", ")
              .append(e.getMessage())
              .append('>');
    }
}

protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }
    if (array == null) {
        buffer.append(fieldName).append("=\"null\"");
        return;
    }
    buffer.append(fieldName).append("=[");
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(", ");
        }
        int unsignedValue = array[i] & 0xFF;
        String hex = Integer.toHexString(unsignedValue).toUpperCase();
        if (hex.length() == 1) {
            hex = "0" + hex;
        }
        buffer.append("0x").append(hex);
    }
    buffer.append("]");
}

