private String parseToken(final char[] terminators) {
    // Return immediately if the source is not initialized
    if (source == null) {
        return null;
    }

    StringBuilder token = new StringBuilder();
    final int sourceLen = source.length();

    try {
        // Scan characters until a terminator or the end of the source
        while (pos < sourceLen) {
            char ch = source.charAt(pos);

            // Check whether the current character is a terminator
            boolean isTerm = false;
            if (terminators != null && terminators.length > 0) {
                for (char term : terminators) {
                    if (ch == term) {
                        isTerm = true;
                        break;
                    }
                }
            }

            // If we hit a terminator, consume it and stop reading the token
            if (isTerm) {
                pos++; // consume terminator for the next call
                break;
            }

            // Otherwise, add to the token and advance position
            token.append(ch);
            pos++;
        }
    } catch (Exception e) {
        // Defensive: in case of unexpected errors return what has been read so far
        // (Could also log the error if logging facilities are available)
    }

    return token.toString();
}

private String parseToken(final char[] terminators) {
    // validate input
    if (terminators == null) {
        throw new IllegalArgumentException("terminators array cannot be null");
    }

    // if there is no source input, return empty token
    if (input == null) {
        return "";
    }

    StringBuilder sb = new StringBuilder();
    int length = input.length();

    // iterate until reaching a terminator or end of input
    while (position < length) {
        char current = input.charAt(position);

        // check if the current character is a terminator
        boolean isTerm = false;
        for (char t : terminators) {
            if (current == t) {
                isTerm = true;
                break;
            }
        }

        if (isTerm) {
            // stop parsing but leave the position pointing at the terminator
            break;
        }

        sb.append(current);
        position++;
    }

    return sb.toString();
}

private String parseToken(final char[] terminators){
    // Validate input
    if (terminators == null) {
        throw new IllegalArgumentException("Terminator array cannot be null.");
    }
    // If terminators are empty we treat as no terminator -> consume rest of source
    if (terminators.length == 0) {
        if (pos >= source.length()) {
            return "";
        }
        String remaining = source.substring(pos);
        pos = source.length();
        return remaining;
    }
    // If source is null or current position beyond source length, return empty token
    if (source == null || pos >= source.length()) {
        return "";
    }
    StringBuilder sb = new StringBuilder();
    try {
        while (pos < source.length()) {
            char ch = source.charAt(pos);
            // Check if current char is a terminating character
            boolean isTerminator = false;
            for (char t : terminators) {
                if (ch == t) {
                    isTerminator = true;
                    break;
                }
            }
            if (isTerminator) {
                break; // stop before consuming terminator
            }
            sb.append(ch);
            pos++;
        }
    } catch (IndexOutOfBoundsException e) {
        // Should not happen, but ensure we don't fail silently
        throw new IllegalStateException("Unexpected end of source while parsing token.", e);
    }
    return sb.toString();
}

