private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        return;
    }
    // If the source list is empty, nothing to do
    if (list.head == null) {
        return;
    }
    // If this list is empty, simply adopt the source list's nodes
    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        // Connect the tail of this list to the head of the source list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    // Update size
    this.size += list.size;
    // Clear the source list
    list.head = null;
    list.tail = null;
    list.size = 0;
}

