        throw new IllegalArgumentException("Source list must not be null");
    }
    if (list == this) {
        return; // nothing to move
    }
    try {
        // If the source list is empty, nothing to do
        if (list.head == null) {
            return;
        }
        // Iterate over each node in the source list
        ListNode<E> srcNode = list.head;
        while (srcNode != null) {
            // Remember the next node before we detach srcNode
            ListNode<E> next = srcNode.next;
            /* Detach srcNode from the source list */
            if (srcNode.prev != null) {
                srcNode.prev.next = srcNode.next;
            } else {
                // srcNode was the head
                list.head = srcNode.next;
            }
            if (srcNode.next != null) {
                srcNode.next.prev = srcNode.prev;
            } else {
                // srcNode was the tail
                list.tail = srcNode.prev;
            }
            srcNode.prev = null;
            srcNode.next = null;
            /* Attach srcNode to the destination list (this list) at the tail */
            srcNode.prev = this.tail;
            if (this.tail != null) {
                this.tail.next = srcNode;
            } else {
                // Destination list was empty
                this.head = srcNode;
            }
            this.tail = srcNode;
            /* Update sizes */
            this.size++;
            if (list.size > 0) {
                list.size--;
            }
            /* Move to the next node in the source list */
            srcNode = next;
        }
    } catch (Exception ex) {
        throw new IllegalStateException("Failed to move nodes from source list", ex);
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list cannot be null");
    }
    if (list == this) {
        return; // nothing to move
    }

    // Determine lock order to avoid deadlock
    Object firstLock = this;
    Object secondLock = list;
    if (System.identityHashCode(this) > System.identityHashCode(list)) {
        firstLock = list;
        secondLock = this;
    }

    synchronized (firstLock) {
        synchronized (secondLock) {
            // If the source list is empty, nothing to do
            if (list.head == null) {
                return;
            }

            // Record source list's boundaries
            ListNode<E> sourceFirst = list.head;
            ListNode<E> sourceLast = list.tail;

            // Append source list to the end of this list
            if (this.tail != null) {
                this.tail.next = sourceFirst;
                sourceFirst.prev = this.tail;
            } else {
                this.head = sourceFirst;
            }
            this.tail = sourceLast;

            // Update sizes
            this.size += list.size;

            // Clear the source list
            list.head = null;
            list.tail = null;
            list.size = 0;
        }
    }
