public ByteVector putInt(final int intValue){
    // Ensure the internal byte array has enough space for 4 new bytes.
    if (a == null) {
        // Initial allocation if the array hasn't been created yet.
        a = new byte[4];
    } else if (pos + 4 > a.length) {
        // Grow the array, ensuring we accommodate the new data.
        int newLen = Math.max(a.length << 1, pos + 4);
        byte[] newArray = new byte[newLen];
        System.arraycopy(a, 0, newArray, 0, pos);
        a = newArray;
    }
    // Store the int in big‑endian order (network byte order).
    a[pos++] = (byte) (intValue >> 24);
    a[pos++] = (byte) (intValue >> 16);
    a[pos++] = (byte) (intValue >> 8);
    a[pos++] = (byte) intValue;
    return this;
}

public ByteVector putInt(final int intValue){
    try {
        // Ensure we have space for 4 more bytes
        ensureCapacity(pos + 4);
        // Store the int in big-endian order
        buf[pos++] = (byte)(intValue >> 24);
        buf[pos++] = (byte)(intValue >> 16);
        buf[pos++] = (byte)(intValue >> 8);
        buf[pos++] = (byte)intValue;
    } catch (Error | RuntimeException e) {
        throw new RuntimeException("Unable to put int into ByteVector", e);
    }
    return this;
}

public ByteVector putInt(final int intValue){
    int required = count + 4;
    if (data == null || data.length < required) {
        int newCapacity = Math.max(required, data == null ? 16 : data.length * 2);
        byte[] newData = new byte[newCapacity];
        if (data != null && count > 0) {
            System.arraycopy(data, 0, newData, 0, count);
        }
        data = newData;
    }
    data[count]     = (byte)(intValue >>> 24);
    data[count + 1] = (byte)(intValue >>> 16);
    data[count + 2] = (byte)(intValue >>> 8);
    data[count + 3] = (byte)(intValue);
    count = required;
    return this;
}

public ByteVector putInt(final int intValue){
    int len = this.len;
    byte[] buf = this.buf;
    int newLen = len + 4;
    if (newLen > buf.length) {
        grow(newLen);
        buf = this.buf; // update in case grow replaced the buffer
    }
    buf[len]     = (byte) intValue;
    buf[len + 1] = (byte) (intValue >> 8);
    buf[len + 2] = (byte) (intValue >> 16);
    buf[len + 3] = (byte) (intValue >> 24);
    this.len = newLen;
    return this;
}

public ByteVector putInt(final int intValue){
    try {
        // Ensure enough space for 4 bytes
        ensureFree(4);
        // Write the integer in big‑endian order
        bytes[position]     = (byte)(intValue >>> 24);
        bytes[position + 1] = (byte)(intValue >>> 16);
        bytes[position + 2] = (byte)(intValue >>> 8);
        bytes[position + 3] = (byte)intValue;
        // Advance the write position
        position += 4;
        return this;
    } catch (final Exception e) {
        // In case of any unexpected error, wrap and rethrow as a runtime exception
        throw new RuntimeException("Failed to put int into byte vector", e);
    }
}

