private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Handle invalid inputs gracefully
    if (graph == null || vertices == null) {
        return false;
    }

    // A graph with 0 or 1 vertex is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    try {
        for (V v1 : vertices) {
            for (V v2 : vertices) {
                if (v1 == v2) {
                    continue; // Skip self-pairs
                }
                // For undirected graphs graph.containsEdge is symmetric
                if (!graph.containsEdge(v1, v2)) {
                    return false; // Missing edge -> not a clique
                }
            }
        }
        return true; // All pairs are connected
    } catch (Exception e) {
        // Any runtime exception (e.g., due to a malformed graph) results in false
        return false;
    }
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Validate parameters
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices must not be null");
    }

    // All vertices must exist in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex " + v + " is not in the graph");
        }
    }

    // Empty or single-vertex subgraphs are trivially cliques
    if (vertices.size() <= 1) {
        return true;
    }

    // Convert to a list for indexed access
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();

    for (int i = 0; i < n; i++) {
        V u = vertexList.get(i);
        for (int j = i + 1; j < n; j++) {
            V v = vertexList.get(j);

            // Check for an edge in either direction (handles directed graphs)
            if (graph.getEdge(u, v) == null && graph.getEdge(v, u) == null) {
                return false; // missing edge between u and v
            }
        }
    }

    return true; // all pairs are connected
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    // A null, empty or single‑vertex set is trivially a clique.
    if (vertices.size() < 2) {
        return true;
    }
    List<V> vertexList = new ArrayList<>(vertices);
    int n = vertexList.size();
    try {
        for (int i = 0; i < n; i++) {
            V vi = vertexList.get(i);
            for (int j = i + 1; j < n; j++) {
                V vj = vertexList.get(j);
                // In an undirected graph, containsEdge checks either direction.
                // For a directed graph, we consider a clique only if edges exist in both directions.
                if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                    return false;
                }
            }
        }
    } catch (Exception e) {
        // Any unexpected runtime issue results in a conservative false.
        return false;
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices set must not be null.");
    }
    // A vertex set with 0 or 1 vertices is trivially a clique.
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph.
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }
    // Convert to a list to avoid repeated iterator creation.
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V vi = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V vj = list.get(j);
            // Check for an undirected edge in either direction.
            boolean connected = graph.containsEdge(vi, vj);
            if (!connected) {
                connected = graph.containsEdge(vj, vi);
            }
            if (!connected) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices){
