    if (size <= 1) {
        return true; // An empty set or a single vertex is always a clique
    }

    // Ensure all vertices are present in the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex " + v + " is not part of the graph");
        }
    }

    // Convert the set to a list for indexed access
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    int n = list.size();

    for (int i = 0; i < n; i++) {
