            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Keys must be of type Integer");
        }
        Integer curr = (Integer) key;
        Integer best = null;
        for (K other : keys) {
            if (other == null || other == key) {
                continue;
            }
            if (!(other instanceof Integer)) {
                continue;
            }
            Integer val = (Integer) other;
            if (val < curr) {
                if (best == null || val > best) {
                    best = val;
                }
            }
        }
        result.add(best);
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty())
        return bounds;
    int n = keys.size();
    for (int i = 0; i < n; i++) {
        K key = keys.get(i);
        Integer maxLower = null;
        if (key == null)
            continue;
        for (int j = 0; j < n; j++) {
            if (i == j)
                continue;
            K other = keys.get(j);
            if (other == null)
                continue;
            try {
                @SuppressWarnings("unchecked")
                int cmp = ((Comparable<? super K>)other).compareTo(key);
                if (cmp < 0) {
                    Integer val;
                    if (other instanceof Number)
                        val = ((Number) other).intValue();
                    else
                        val = other.hashCode();
                    if (maxLower == null || val > maxLower)
                        maxLower = val;
                }
            } catch (ClassCastException | NullPointerException e) {
                // If elements are not comparable or comparison fails, skip this pair
            }
        }
        if (maxLower == null)
            bounds.add(Integer.MIN_VALUE);
        else
            bounds.add(maxLower);
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        if (!(key instanceof Integer)) {
            throw new IllegalArgumentException("Key must be an Integer");
        }
        int current = (Integer) key;
        Integer best = null;
        for (K other : keys) {
            if (other == null || !(other instanceof Integer)) {
                continue;
            }
            int candidate = (Integer) other;
            if (candidate < current && (best == null || candidate > best)) {
                best = candidate;
            }
        }
        lowerBounds.add(best);
    }
    return lowerBounds;
