    boolean isAbsolute = path.startsWith("/");

    // Split base path into components, ignoring empty segments
    String[] baseParts = path.split("/");
    ArrayDeque<String> stack = new ArrayDeque<>();
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            stack.addLast(part);
        }
    }

    // If the base path denotes a file (does not end with slash), drop the file component
    if (!path.endsWith("/") && !stack.isEmpty()) {
        stack.removeLast();
    }

