                stack.removeLast();
            } else {
                // If the stack is empty, do nothing (cannot go above root)
            }
        } else {
            stack.addLast(part);
        }
    }

    // Reconstruct the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }

    Iterator<String> it = stack.iterator();
    while (it.hasNext()) {
        result.append(it.next());
        if (it.hasNext()) {
            result.append("/");
        }
    }

    // If the result is empty, return "." to represent the current directory
    return result.length() == 0 ? "." : result.toString();
