public static String applyRelativePath(String path, String relativePath) {
    // Handle null inputs gracefully
    if (path == null || relativePath == null) {
        return null;
    }
    try {
        // Normalize relativePath leading/trailing slashes for later processing
        String trimmedRelative = relativePath.trim();
        if (trimmedRelative.isEmpty()) {
            return path;
        }

        // Determine if the relative path is absolute
        boolean relAbsolute = trimmedRelative.startsWith("/");

        // Split the base path into components
        java.util.List<String> baseParts = new java.util.ArrayList<>();
        boolean absolute = path.startsWith("/");
        for (String token : path.split("/")) {
            if (!token.isEmpty()) {
                baseParts.add(token);
            }
        }

        // If the relative path is absolute, discard the base path components
        if (relAbsolute) {
            baseParts.clear();
            absolute = true; // resulting path is absolute
        }

        // Process the relative path components
        for (String token : trimmedRelative.split("/")) {
            if (token.isEmpty() || token.equals(".")) {
                // Skip empty or current directory references
                continue;
            }
            if (token.equals("..")) {
                if (!baseParts.isEmpty()) {
                    baseParts.remove(baseParts.size() - 1);
                }
                // If at root, ignore further ".."
                continue;
            }
            baseParts.add(token);
        }

        // Reconstruct the final path
        StringBuilder result = new StringBuilder();
        if (absolute) {
            result.append("/");
        }
        for (int i = 0; i < baseParts.size(); i++) {
            result.append(baseParts.get(i));
            if (i < baseParts.size() - 1) {
                result.append("/");
            }
        }

        // Handle the case where result is empty but absolute
        if (result.length() == 0 && absolute) {
            return "/";
        }
        return result.toString();
    } catch (Exception e) {
        // In case of unexpected errors, return null
        return null;
    }
}

