        return (current - timestamp) > expiredThreshold;
    }catch(Exception e){
        throw new RuntimeException("Error while checking expiration", e);
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // Validate the input parameters.  If either is non‑positive, we consider the metric
        // expired because we cannot reliably compute the age.
        if (timestamp <= 0 || expiredThreshold <= 0) {
            return true;
        }

        long now = System.currentTimeMillis();

        // If the timestamp is in the future, we treat the metric as not expired.
        if (now < timestamp) {
            return false;
        }

        // The metric is expired if the age (now - timestamp) exceeds the allowed threshold.
        return (now - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In case of unexpected errors (e.g., arithmetic overflow), be conservative
        // and indicate that the metric should be considered expired.
        return true;
    }
}

