protected void append(LoggingEvent event){
    // Guard against null event
    if (event == null) {
        return;
    }

    // Retrieve the message from the event, handling any potential exceptions
    String message;
    try {
        message = event.getFormattedMessage();
    } catch (Exception ex) {
        // Fallback: use the raw message if formatted message fails
        Object raw = event.getMessage();
        message = raw == null ? null : raw.toString();
    }

    // If the message is null or empty, nothing to send
    if (message == null || message.isEmpty()) {
        return;
    }

    // If there are no connected clients, exit early
    if (connectedClients == null || connectedClients.isEmpty()) {
        return;
    }

    // Send the message to each connected client, handling individual failures gracefully
    for (Client client : connectedClients) {
        try {
            client.write(message);
        } catch (Exception ex) {
            // Log the failure without interrupting the loop
            System.err.println("Failed to write log message to client: " + ex);
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return; // nothing to log
    }

    String message = event.getRenderedMessage();
    if (message == null) {
        return; // nothing to send
    }

    // Iterate over all connected clients (assumed to be a collection of Writers/PrintWriters)
    // and write the message to each one.  Any failures are logged and the faulty client
    // is removed from the collection so that it does not affect future log writes.
    Iterator<Writer> it = connectedClients.iterator(); // connectedClients assumed to exist
    while (it.hasNext()) {
        Writer clientWriter = it.next();
        try {
            clientWriter.write(message);
            clientWriter.write(System.lineSeparator());
            clientWriter.flush();
        } catch (IOException ioEx) {
            // Log the failure if a logger is available and remove the client
            if (logger != null) {
                logger.error("Failed to write log message to a client", ioEx);
            }
            try {
                clientWriter.close();
            } catch (IOException closeEx) {
                // ignore close exception
            }
            it.remove(); // remove faulty client from collection
        }
    }
}

