protected void append(LoggingEvent event) {
    // Validate the event argument
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }

    // Build the formatted message string (include a line terminator)
    String message;
    try {
        message = event.getRenderedMessage();
    } catch (Exception e) {
        // If we cannot render the message, skip processing this event
        return;
    }
    String line = message + System.lineSeparator();

    // Convert the message to bytes using the configured encoding
    byte[] payload;
    try {
        if (encoding != null) {
            payload = line.getBytes(encoding);
        } else {
            payload = line.getBytes();
        }
    } catch (UnsupportedEncodingException e) {
        // Fall back to the platform default encoding
        payload = line.getBytes();
    }

    // Send the payload to every connected client
    for (Socket client : connectedClients) {
        try {
            OutputStream out = client.getOutputStream();
            out.write(payload);
            out.flush();
        } catch (IOException ioEx) {
            // If we hit an IO error, close and remove the client
            try {
                client.close();
            } catch (IOException closeEx) {
                // ignore
            }
            connectedClients.remove(client);
        }
    }
}

protected void append(LoggingEvent event) {
    // Safely handle null input
    if (event == null) {
        return; // nothing to log
    }

    // Try to obtain the rendered message; fall back to empty string on failure
    String renderedMsg;
    try {
        renderedMsg = event.getRenderedMessage();
        if (renderedMsg == null) {
            renderedMsg = "";
        }
    } catch (Exception e) {
        // If something goes wrong while getting the message, log the error and return
        if (logger != null) {
            logger.error("Failed to retrieve rendered message from event", e);
        }
        return;
    }

    // Prefix with log level so the client can see severity
    String level = event.getLevel() != null ? event.getLevel().toString() : "UNKNOWN";
    String messageToSend = level + " - " + renderedMsg;

    // If no clients are connected, simply exit
    if (clients == null || clients.isEmpty()) {
        return;
    }

    // Iterate over all connected clients and send the message
    for (Object clientObj : clients) {
        try {
            if (clientObj == null) {
                continue; // skip any null entries
            }
            // Attempt to call a send/write method; assume a common interface
            if (clientObj instanceof ClientSender) {
                ((ClientSender) clientObj).send(messageToSend);
            } else if (clientObj instanceof java.net.Socket) {
                java.net.Socket socket = (java.net.Socket) clientObj;
                java.io.PrintWriter out = new java.io.PrintWriter(socket.getOutputStream(), true);
                out.println(messageToSend);
            } else {
                // Unknown client type; attempt reflection as a last resort
                java.lang.reflect.Method m = clientObj.getClass().getMethod("write", java.lang.String.class);
                m.invoke(clientObj, messageToSend);
            }
        } catch (Exception e) {
            // Log failures but continue sending to other clients
            if (logger != null) {
                logger.warn("Error sending log event to client [" + clientObj + "]", e);
            }
            // Continue with next client
        }
    }
}

