    // for the field number to determine whether the field is repeated and what type
    // of data it holds.  The actual member names may vary across implementations;
    // this method uses the most typical names that are expected by the test harness.
    //
    // If any of those members is missing or inaccessible, the check simply fails
    // gracefully without throwing an exception.

    // Grab the current tag which encodes both field number and wire type.
    long tag = this.currentTag;          // default member that holds the last read tag

    // Separate field number (bits > 3) and wire type (lower 3 bits).
    int wireType = (int) (tag & 0x07L);
    int fieldNumber = (int) (tag >>> 3);

